/* find.js — behaviour for /curriculum/find/.
 *
 * Reads data/curriculum-find-index.json (generated by scripts/generate-curriculum-find-index.mjs) and ranks it
 * with ./find-engine.js. The query lives in ?q=, so a refresh, the back button and a shared link land on the same
 * results. "My list" is localStorage on this device only (key below); it holds titles and URLs, never anything
 * about a student. Every listener is attached here; the page has no inline handlers. */

import { initCollections, saveButton, syncSaveButtons } from "./collections-ui.js";
import { $, el, facts as factsOf } from "./dom.js";
import {
  audienceLabel,
  companions,
  kindLabel,
  languagePageLink,
  search,
  standardLabel,
} from "./find-engine.js";
import { initPlan, renderPath, renderPlan, resumeInfo } from "./plan-ui.js";

const INDEX_URL = "/data/curriculum-find-index.json";
const PAGE = 12;
const MODES = new Set(["search", "plan", "path"]);

let index = null;
let shown = PAGE;
let last = null;

/* ---------- results ----------------------------------------------------- */

function metaLine(doc) {
  const bits = [];
  if (doc.u) bits.push(`Unit ${doc.u}${index.units[doc.u] ? `: ${index.units[doc.u]}` : ""}`);
  if (doc.l) bits.push(`Lesson ${doc.l}`);
  if (doc.s) bits.push(`${doc.s} ${standardLabel(index, doc.s)}`.trim());
  return bits.join(" · ");
}
const facts = (doc) => factsOf(doc, audienceLabel);

function resultItem({ doc, why }) {
  const save = saveButton(doc);
  const pals = companions(index, doc);
  const head = el(
    "div",
    { class: "find-item-head" },
    el("span", { class: "find-kind", text: kindLabel(doc.k) }),
    el("h3", {}, el("a", { href: doc.p, "data-doc": doc.p, text: doc.t })),
  );
  const parts = [head];
  const meta = metaLine(doc);
  if (meta) parts.push(el("p", { class: "find-meta", text: meta }));
  if (doc.d) parts.push(el("p", { class: "find-desc", text: doc.d }));
  parts.push(
    el(
      "ul",
      { class: "find-facts", "aria-label": "About this resource" },
      facts(doc).map((t) => el("li", { text: t })),
    ),
  );
  if (why.length)
    parts.push(
      el("p", { class: "find-why" }, el("strong", { text: "Why this: " }), why.join(" · ")),
    );
  const foot = el("div", { class: "find-item-foot" }, save);
  if (doc.alt)
    foot.append(
      el("a", {
        href: doc.alt,
        class: "find-alt",
        text: `Also as ${doc.alt.endsWith(".docx") ? "Word" : "PDF"}`,
      }),
    );
  if (pals.length) {
    foot.append(
      el(
        "details",
        { class: "find-pals" },
        el("summary", { text: `Goes well with (${pals.length})` }),
        el(
          "ul",
          {},
          pals.map((d) =>
            el(
              "li",
              {},
              el("span", { class: "find-kind", text: kindLabel(d.k) }),
              el("a", { href: d.p, "data-doc": d.p, text: d.t }),
            ),
          ),
        ),
      ),
    );
  }
  parts.push(foot);
  return el(
    "li",
    { class: "find-item", style: doc.u ? `--u: var(--unit-${doc.u})` : null },
    ...parts,
  );
}

/* ---------- "Understood as" -------------------------------------------- */

function understood(q) {
  const chips = [];
  for (const t of q.topics) chips.push(["Topic", t.replace(/-/g, " ")]);
  for (const s of q.standards) if (!q.topics.length) chips.push(["Standard", s]);
  if (q.lesson) chips.push(["Lesson", q.lesson]);
  if (q.unit != null) chips.push(["Unit", String(q.unit)]);
  if (q.kind) chips.push(["Kind", kindLabel(q.kind)]);
  if (q.audience) chips.push(["For", audienceLabel(q.audience)]);
  if (q.printable) chips.push(["Format", "printable"]);
  if (q.level) chips.push(["Level", q.level === "support" ? "extra support" : "challenge"]);
  if (q.ell) chips.push(["Language", "English-learner supports"]);
  if (q.short) chips.push(["Time", q.minutes ? `about ${q.minutes} minutes` : "short"]);
  for (const w of q.rest) chips.push(["Words", w]);
  const box = $("find-understood");
  box.hidden = chips.length === 0;
  const notes = [];
  if (q.short)
    notes.push(
      "Time is not recorded for each resource, so shorter formats (practice, games, family pages) come first.",
    );
  if (q.grades.length && !q.grades.includes(6))
    notes.push(
      `This course is Grade 6. For grade ${q.grades.join("–")} language practice, try The Language Page below.`,
    );
  box.replaceChildren(
    el("h2", { class: "find-understood-title", text: "Find read this as" }),
    el(
      "ul",
      {},
      chips.map(([k, v]) => el("li", {}, el("span", { text: `${k}: ` }), v)),
    ),
    ...notes.map((n) => el("p", { class: "find-understood-note", text: n })),
  );
}

function languagePanel(q, languageOnly) {
  const href = languagePageLink(q);
  const box = $("find-lp");
  box.hidden = !href;
  if (!href) return;
  const lead = languageOnly
    ? "This sounds like language practice. The Language Page has listening, speaking, reading, writing and vocabulary activities with visual and Spanish supports."
    : "For the English that goes with this math — vocabulary, sentence frames, speaking and listening practice — The Language Page has activities by grade band.";
  box.replaceChildren(
    el("h2", { text: "On The Language Page" }),
    el("p", { text: lead }),
    el("a", { class: "find-lp-go", href, text: "Search The Language Page" }),
  );
}

/* ---------- run -------------------------------------------------------- */

function run(raw, { push = false } = {}) {
  const query = String(raw || "").trim();
  const url = new URL(location.href);
  url.search = query ? new URLSearchParams({ q: query }).toString() : "";
  if (push) history.pushState({}, "", url);
  setMode("search");
  $("find-q").value = query;
  $("find-start").hidden = Boolean(query);
  $("find-examples").hidden = Boolean(query);
  if (!query) {
    renderResume();
    $("find-list").replaceChildren();
    $("find-status").textContent = "";
    $("find-understood").hidden = true;
    $("find-lp").hidden = true;
    $("find-more").hidden = true;
    return;
  }
  last = search(index, query, { limit: 200 });
  shown = PAGE;
  understood(last.query);
  languagePanel(last.query, last.languageOnly);
  paint();
}

function paint() {
  const { results } = last;
  const n = results.length;
  $("find-status").textContent =
    n === 0
      ? last.languageOnly
        ? "No Grade 6 math resources match — see The Language Page below."
        : "Nothing matched. Try fewer words, a topic like “area” or “ratios”, or a lesson number like 6-6."
      : `${n === 200 ? "200+" : n} resource${n === 1 ? "" : "s"} found. Showing the best ${Math.min(shown, n)}.`;
  $("find-list").replaceChildren(...results.slice(0, shown).map(resultItem));
  $("find-more").hidden = shown >= n;
  syncSaveButtons();
}

/* ---------- modes: search, plan a set, practice path -------------------------------------------- */

function setMode(mode) {
  const wrap = document.querySelector(".find-wrap");
  wrap.dataset.mode = mode;
  for (const a of document.querySelectorAll(".find-modes a")) {
    if (a.dataset.mode === mode) a.setAttribute("aria-current", "page");
    else a.removeAttribute("aria-current");
  }
  const titles = { search: "Find a resource", plan: "Plan a set", path: "My practice path" };
  document.title = `${titles[mode]} — EduWonderLab Grade 6 Math`;
}

function route() {
  const p = new URLSearchParams(location.search);
  const mode = MODES.has(p.get("mode")) ? p.get("mode") : "search";
  if (mode === "plan") {
    setMode("plan");
    renderPlan();
  } else if (mode === "path") {
    setMode("path");
    renderPath();
  } else run(p.get("q"));
}

function renderResume() {
  const box = $("find-resume");
  const r = resumeInfo();
  box.hidden = !r;
  if (!r) return;
  box.replaceChildren(
    el("a", { href: `?mode=path&lesson=${r.lesson}` },
      el("strong", { text: "Continue my practice path" }),
      el("span", { text: `${r.title} · ${r.done} of ${r.total} steps done` }),
    ),
  );
}

async function boot() {
  $("find-form").addEventListener("submit", (e) => {
    e.preventDefault();
    run($("find-q").value, { push: true });
  });
  $("find-examples").addEventListener("click", (e) => {
    const a = e.target.closest("a");
    if (!a) return;
    e.preventDefault();
    run(new URL(a.href).searchParams.get("q"), { push: true });
    $("find-results-title").scrollIntoView({ block: "start" });
  });
  $("find-more").addEventListener("click", () => {
    const first = shown;
    shown += PAGE;
    paint();
    $("find-list").children[first]?.querySelector("a")?.focus();
  });
  // The mode links and in-page links to another mode change the view without a page load.
  document.querySelector(".find-wrap").addEventListener("click", (e) => {
    const a = e.target.closest("a[href^='?mode='], .find-modes a");
    if (!a || e.defaultPrevented || e.metaKey || e.ctrlKey || e.shiftKey) return;
    e.preventDefault();
    history.pushState({}, "", new URL(a.href, location.href));
    route();
  });
  addEventListener("popstate", route);
  document.addEventListener("find:navigate", route);
  document.addEventListener("find:forgot", route);

  $("find-status").textContent = "Loading the resource index…";
  try {
    const res = await fetch(INDEX_URL);
    if (!res.ok) throw new Error(String(res.status));
    index = await res.json();
  } catch {
    $("find-status").textContent =
      "The resource index did not load. Check the connection and refresh, or open All resources instead.";
    return;
  }
  $("find-status").textContent = "";
  initCollections(index);
  initPlan(index);
  route();
}

boot();
